-- Setup for the synthetic portfolio dataset.
-- This script drops and recreates the four project tables in general_ledger_project.
-- Northstar Services Ltd: synthetic 2025 general ledger (GBP)
-- MySQL Workbench: File > Open SQL Script, then click the lightning bolt.
CREATE DATABASE IF NOT EXISTS general_ledger_project CHARACTER SET utf8mb4;
USE general_ledger_project;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS ledger_lines;
DROP TABLE IF EXISTS journals;
DROP TABLE IF EXISTS budgets;
DROP TABLE IF EXISTS accounts;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE accounts (account_code VARCHAR(4) PRIMARY KEY, account_name VARCHAR(100), category VARCHAR(30), normal_balance VARCHAR(10));
CREATE TABLE budgets (month CHAR(7), department VARCHAR(30), account_code VARCHAR(4), budget_amount DECIMAL(12,2), PRIMARY KEY (month, department, account_code), FOREIGN KEY (account_code) REFERENCES accounts(account_code));
CREATE TABLE journals (journal_id INT PRIMARY KEY, posted_at DATETIME, document_no VARCHAR(50), department VARCHAR(30), supplier VARCHAR(100), payment_method VARCHAR(30), entry_type VARCHAR(30), employee VARCHAR(80), approver VARCHAR(80), description VARCHAR(255));
CREATE TABLE ledger_lines (line_id INT PRIMARY KEY, journal_id INT, account_code VARCHAR(4), debit DECIMAL(12,2) NOT NULL DEFAULT 0, credit DECIMAL(12,2) NOT NULL DEFAULT 0, FOREIGN KEY (journal_id) REFERENCES journals(journal_id), FOREIGN KEY (account_code) REFERENCES accounts(account_code), CHECK ((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
START TRANSACTION;
COMMIT;
-- Check: expected 1300 journals, 2600 lines, no unbalanced journals.
SELECT COUNT(*) AS journal_count FROM journals;
SELECT COUNT(*) AS line_count FROM ledger_lines;
SELECT journal_id FROM ledger_lines GROUP BY journal_id HAVING ABS(SUM(debit)-SUM(credit))>0.001;
